BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SEQUENCE IF NOT EXISTS forge_evidence_ledger_seq AS bigint;
CREATE TABLE IF NOT EXISTS forge_evidence_chain_state(id smallint PRIMARY KEY CHECK(id=1),chain_head_seq bigint NOT NULL DEFAULT 0,chain_head_hash char(64) NOT NULL DEFAULT repeat('0',64),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO forge_evidence_chain_state(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS evidence_ledger(ledger_seq bigint PRIMARY KEY DEFAULT nextval('forge_evidence_ledger_seq'),event_id char(64) NOT NULL UNIQUE,tenant_id text,project_id text,episode_id text,actor text NOT NULL,event_type text NOT NULL,source_table text NOT NULL,operation text NOT NULL CHECK(operation IN('INSERT','UPDATE','DELETE')),target_type text NOT NULL,target_id text NOT NULL,request_id text,causal_event_id char(64),artifact_id text,provenance_id text,occurred_at timestamptz NOT NULL DEFAULT now(),payload_digest char(64) NOT NULL,prev_hash char(64) NOT NULL,event_hash char(64) NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS evidence_ledger_tenant_seq_idx ON evidence_ledger(tenant_id,ledger_seq);
CREATE INDEX IF NOT EXISTS evidence_ledger_project_seq_idx ON evidence_ledger(project_id,ledger_seq);
CREATE INDEX IF NOT EXISTS evidence_ledger_request_idx ON evidence_ledger(request_id);
CREATE INDEX IF NOT EXISTS evidence_ledger_target_idx ON evidence_ledger(target_type,target_id,ledger_seq DESC);
CREATE TABLE IF NOT EXISTS evidence_checkpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,checkpoint_seq bigint NOT NULL,chain_head_hash char(64) NOT NULL,event_count bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,checkpoint_seq));
CREATE TABLE IF NOT EXISTS evidence_archive_manifests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,from_seq bigint NOT NULL,to_seq bigint NOT NULL,event_count bigint NOT NULL,archive_digest char(64) NOT NULL,chain_head_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_seq<=to_seq),UNIQUE(tenant_id,from_seq,to_seq));
CREATE TABLE IF NOT EXISTS evidence_archive_events(tenant_id text NOT NULL,ledger_seq bigint NOT NULL,event_id char(64) NOT NULL UNIQUE,project_id text,episode_id text,actor text NOT NULL,event_type text NOT NULL,source_table text NOT NULL,operation text NOT NULL,target_type text NOT NULL,target_id text NOT NULL,request_id text,causal_event_id char(64),artifact_id text,provenance_id text,occurred_at timestamptz NOT NULL,payload_digest char(64) NOT NULL,prev_hash char(64) NOT NULL,event_hash char(64) NOT NULL,archive_manifest_id uuid REFERENCES evidence_archive_manifests(id) ON DELETE RESTRICT,archived_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,ledger_seq));
CREATE TABLE IF NOT EXISTS evidence_diagnostics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text,diagnostic_type text NOT NULL,severity text NOT NULL CHECK(severity IN('INFO','WARN','ERROR','CRITICAL')),from_seq bigint,to_seq bigint,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_quarantine(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text,ledger_seq bigint,event_id char(64),reason text NOT NULL,diagnostics jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_retention_policy(tenant_id text PRIMARY KEY,archive_after_days integer NOT NULL DEFAULT 30 CHECK(archive_after_days>=0),retain_forever boolean NOT NULL DEFAULT true,max_export_events integer NOT NULL DEFAULT 5000 CHECK(max_export_events BETWEEN 1 AND 50000),updated_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION forge_evidence_scope(row_data jsonb) RETURNS TABLE(tenant_id text,project_id text,episode_id text,artifact_id text,provenance_id text) AS $$ DECLARE provider_run_value text; BEGIN tenant_id=NULLIF(row_data->>'tenant_id','');project_id=NULLIF(row_data->>'project_id','');episode_id=NULLIF(row_data->>'episode_id','');artifact_id=NULLIF(row_data->>'artifact_id','');provenance_id=NULLIF(row_data->>'version_id','');IF provenance_id IS NULL THEN provenance_id=NULLIF(row_data->>'target_version_id','');END IF;provider_run_value=NULLIF(row_data->>'provider_run_id','');IF episode_id IS NULL AND provider_run_value IS NOT NULL THEN SELECT r.episode_id INTO episode_id FROM provider_runs r WHERE r.id=provider_run_value;END IF;IF episode_id IS NULL AND artifact_id IS NOT NULL THEN SELECT a.episode_id INTO episode_id FROM artifacts a WHERE a.id=artifact_id;END IF;IF episode_id IS NULL AND provenance_id IS NOT NULL THEN SELECT v.episode_id INTO episode_id FROM version_records v WHERE v.id=provenance_id;END IF;IF project_id IS NULL AND episode_id IS NOT NULL THEN SELECT e.project_id INTO project_id FROM episodes e WHERE e.id=episode_id;END IF;IF tenant_id IS NULL AND project_id IS NOT NULL THEN SELECT p.tenant_id INTO tenant_id FROM projects p WHERE p.id=project_id;END IF;RETURN NEXT;END;$$ LANGUAGE plpgsql STABLE;

CREATE OR REPLACE FUNCTION forge_capture_evidence() RETURNS trigger AS $$ DECLARE row_data jsonb;scope record;target_id text;request_id_value text;causal_event_id_value char(64);actor_value text;payload_digest_value char(64);event_id_value char(64);existing_digest char(64);previous_hash char(64);next_seq bigint;event_hash_value char(64);BEGIN row_data=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;SELECT * INTO scope FROM forge_evidence_scope(row_data);target_id=COALESCE(row_data->>'id',row_data->>'event_id',row_data->>'job_id',row_data->>'run_id',row_data->>'jti',row_data->>'version_id',row_data->>'artifact_id',row_data->>'project_id',row_data->>'episode_id',row_data->>'release_id',row_data->>'worker_id',row_data->>'key',row_data->>'scheduler_key','unknown');request_id_value=NULLIF(current_setting('forge.request_id',true),'');causal_event_id_value=NULLIF(current_setting('forge.causal_event_id',true),'');actor_value=COALESCE(NULLIF(current_setting('forge.actor',true),''),NULLIF(row_data->>'actor',''),NULLIF(row_data->>'created_by',''),'system');payload_digest_value=encode(digest(row_data::text,'sha256'),'hex');event_id_value=encode(digest(concat_ws('|',COALESCE(scope.tenant_id,''),TG_TABLE_NAME,TG_OP,target_id,COALESCE(request_id_value,''),payload_digest_value),'sha256'),'hex');SELECT payload_digest INTO existing_digest FROM evidence_ledger WHERE event_id=event_id_value FOR SHARE;IF existing_digest IS NOT NULL THEN IF existing_digest<>payload_digest_value THEN RAISE EXCEPTION 'evidence event identity collision for %',event_id_value USING ERRCODE='integrity_constraint_violation';END IF;RETURN COALESCE(NEW,OLD);END IF;SELECT chain_head_hash INTO previous_hash FROM forge_evidence_chain_state WHERE id=1 FOR UPDATE;next_seq=nextval('forge_evidence_ledger_seq');event_hash_value=encode(digest(concat_ws('|',next_seq::text,event_id_value,previous_hash,COALESCE(scope.tenant_id,''),COALESCE(scope.project_id,''),COALESCE(scope.episode_id,''),actor_value,TG_TABLE_NAME,TG_OP,target_id,COALESCE(request_id_value,''),COALESCE(causal_event_id_value,''),payload_digest_value),'sha256'),'hex');INSERT INTO evidence_ledger(ledger_seq,event_id,tenant_id,project_id,episode_id,actor,event_type,source_table,operation,target_type,target_id,request_id,causal_event_id,artifact_id,provenance_id,payload_digest,prev_hash,event_hash) VALUES(next_seq,event_id_value,scope.tenant_id,scope.project_id,scope.episode_id,actor_value,'DATA_MUTATION',TG_TABLE_NAME,TG_OP,TG_TABLE_NAME,target_id,request_id_value,causal_event_id_value,scope.artifact_id,scope.provenance_id,payload_digest_value,previous_hash,event_hash_value);UPDATE forge_evidence_chain_state SET chain_head_seq=next_seq,chain_head_hash=event_hash_value,updated_at=now() WHERE id=1;RETURN COALESCE(NEW,OLD);END;$$ LANGUAGE plpgsql;

DO $$ DECLARE table_name text;row_data jsonb;scope record;target_id text;payload_digest_value char(64);event_id_value char(64);previous_hash char(64);next_seq bigint;event_hash_value char(64);actor_value text;BEGIN FOREACH table_name IN ARRAY ARRAY['projects','project_members','episodes','version_records','version_dependencies','artifacts','provider_runs','cost_records','qa_results','approvals','audit_events','security_audit_events','forge_jobs','forge_outbox','forge_idempotency_keys','forge_scheduler_events','forge_scheduler_state','usage_pricing','usage_budgets','usage_reservations','usage_events','operational_incidents','incident_rules','incident_maintenance_windows','incident_escalation_policies','incident_occurrences','incident_actions','incident_notification_state','incident_rate_buckets','runtime_policy_versions','runtime_policy_heads','runtime_feature_flags','runtime_secrets','runtime_config_audit','runtime_boot_snapshots','runtime_worker_snapshots','forge_release_manifests','forge_release_checkpoints','forge_schema_drift_snapshots','forge_worker_fences','forge_feature_flag_rollouts','forge_release_state','forge_release_approvals','forge_execution_runs','publish_runs'] LOOP IF to_regclass('public.'||table_name) IS NULL THEN CONTINUE;END IF;FOR row_data IN EXECUTE format('SELECT to_jsonb(t) FROM %I t ORDER BY t.ctid',table_name) LOOP SELECT * INTO scope FROM forge_evidence_scope(row_data);target_id=COALESCE(row_data->>'id',row_data->>'event_id',row_data->>'job_id',row_data->>'run_id',row_data->>'jti',row_data->>'version_id',row_data->>'artifact_id',row_data->>'project_id',row_data->>'episode_id',row_data->>'release_id',row_data->>'worker_id',row_data->>'key',row_data->>'scheduler_key','unknown');actor_value=COALESCE(NULLIF(row_data->>'actor',''),NULLIF(row_data->>'created_by',''),NULLIF(row_data->>'updated_by',''),'legacy-backfill');payload_digest_value=encode(digest(row_data::text,'sha256'),'hex');event_id_value=encode(digest(concat_ws('|',COALESCE(scope.tenant_id,''),table_name,'LEGACY',target_id,payload_digest_value),'sha256'),'hex');IF EXISTS(SELECT 1 FROM evidence_ledger WHERE event_id=event_id_value) THEN CONTINUE;END IF;SELECT chain_head_hash INTO previous_hash FROM forge_evidence_chain_state WHERE id=1 FOR UPDATE;next_seq=nextval('forge_evidence_ledger_seq');event_hash_value=encode(digest(concat_ws('|',next_seq::text,event_id_value,previous_hash,COALESCE(scope.tenant_id,''),COALESCE(scope.project_id,''),COALESCE(scope.episode_id,''),actor_value,table_name,'INSERT',target_id,'legacy-backfill','',payload_digest_value),'sha256'),'hex');INSERT INTO evidence_ledger(ledger_seq,event_id,tenant_id,project_id,episode_id,actor,event_type,source_table,operation,target_type,target_id,request_id,artifact_id,provenance_id,payload_digest,prev_hash,event_hash) VALUES(next_seq,event_id_value,scope.tenant_id,scope.project_id,scope.episode_id,actor_value,'LEGACY_SNAPSHOT',table_name,'INSERT',table_name,target_id,'legacy-backfill',scope.artifact_id,scope.provenance_id,payload_digest_value,previous_hash,event_hash_value);UPDATE forge_evidence_chain_state SET chain_head_seq=next_seq,chain_head_hash=event_hash_value,updated_at=now() WHERE id=1;END LOOP;END LOOP;END $$;

CREATE OR REPLACE FUNCTION forge_evidence_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'evidence history is append-only';END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS evidence_ledger_no_update ON evidence_ledger;CREATE TRIGGER evidence_ledger_no_update BEFORE UPDATE OR DELETE ON evidence_ledger FOR EACH ROW EXECUTE FUNCTION forge_evidence_immutable();
DROP TRIGGER IF EXISTS evidence_archive_no_update ON evidence_archive_events;CREATE TRIGGER evidence_archive_no_update BEFORE UPDATE OR DELETE ON evidence_archive_events FOR EACH ROW EXECUTE FUNCTION forge_evidence_immutable();
DO $$ DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['projects','project_members','episodes','version_records','version_dependencies','artifacts','provider_runs','cost_records','qa_results','approvals','audit_events','security_audit_events','forge_jobs','forge_outbox','forge_idempotency_keys','forge_scheduler_events','forge_scheduler_state','usage_pricing','usage_budgets','usage_reservations','usage_events','operational_incidents','incident_rules','incident_maintenance_windows','incident_escalation_policies','incident_occurrences','incident_actions','incident_notification_state','incident_rate_buckets','runtime_policy_versions','runtime_policy_heads','runtime_feature_flags','runtime_secrets','runtime_config_audit','runtime_boot_snapshots','runtime_worker_snapshots','forge_release_manifests','forge_release_checkpoints','forge_schema_drift_snapshots','forge_worker_fences','forge_feature_flag_rollouts','forge_release_state','forge_release_approvals','forge_execution_runs','publish_runs','evidence_diagnostics','evidence_quarantine'] LOOP IF to_regclass('public.'||table_name) IS NOT NULL THEN EXECUTE format('DROP TRIGGER IF EXISTS evidence_capture_%s ON %I',table_name,table_name);EXECUTE format('CREATE TRIGGER evidence_capture_%s AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION forge_capture_evidence()',table_name,table_name);END IF;END LOOP;END $$;
COMMIT;
